        return Math.Min(baseRate + bonus, MaxRatePoints);
    }

    public static int DiscountCents(LoyaltyTier tier, int subtotalCents) =>
        (int)((long)subtotalCents * RatePoints(tier, subtotalCents) / 100);
}
